import { MakeLogicType, actions, kea, path, reducers } from 'kea'
import { actionToUrl, router, urlToAction } from 'kea-router'

import { Breadcrumb } from '~/types'

export type TransformationsSceneView = 'list' | 'flow'

const DEFAULT_VIEW: TransformationsSceneView = 'list'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface transformationsSceneLogicValues {
    breadcrumbs: Breadcrumb[]
    view: TransformationsSceneView
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface transformationsSceneLogicActions {
    setView: (view: TransformationsSceneView) => {
        view: TransformationsSceneView
    }
}

export type transformationsSceneLogicType = MakeLogicType<
    transformationsSceneLogicValues,
    transformationsSceneLogicActions
>

export const transformationsSceneLogic = kea<transformationsSceneLogicType>([
    path(['scenes', 'data-pipelines', 'transformationsSceneLogic']),
    actions({
        setView: (view: TransformationsSceneView) => ({ view }),
    }),
    reducers({
        view: [
            DEFAULT_VIEW as TransformationsSceneView,
            {
                setView: (_, { view }) => view,
            },
        ],
    }),
    // pinned: the `view` search param is in shared links, so renaming it breaks them.
    actionToUrl(({ values }) => ({
        setView: () => {
            const { view: _, ...otherParams } = router.values.searchParams
            const searchParams = values.view === DEFAULT_VIEW ? otherParams : { ...otherParams, view: values.view }
            return [router.values.location.pathname, searchParams, router.values.hashParams]
        },
    })),
    urlToAction(({ actions, values }) => ({
        '/data-management/transformations': (_, searchParams) => {
            const view: TransformationsSceneView = searchParams.view === 'flow' ? 'flow' : DEFAULT_VIEW
            if (view !== values.view) {
                actions.setView(view)
            }
        },
    })),
    () => ({
        selectors: {
            breadcrumbs: [
                () => [],
                (): Breadcrumb[] => {
                    return [
                        {
                            key: 'Transformations',
                            name: 'Transformations',
                            iconType: 'data_pipeline',
                        },
                    ]
                },
            ],
        },
    }),
])
